    private const uint OP_APPLY = 1, OP_ADD = 2, OP_NEW = 3, OP_APPLY_ELEM = 4;   // ak_bdr_rec.op
    private static void Replay(ListMetricsResponse t, byte* b, byte* p, int len)
    {
